pr.solution:
def find_first(s, ch):
    index = -1
    i = 0
    found = False
    while i < len(s) and not found:
        if s[i] == ch:
            index = i
            found = True
        i = i + 1
    return index

def quotes_ok(s):
    pair = 0
    for i in range(0, len(s)):
        if s[i] == "\"":
            pair = pair + 1
    return pair % 2 == 0

