def col_avg(S, c):
    t = 0
    for k in range(0, len(S)):
        t = t + S[k][c]
    return t / len(S)

def window(M):
    P = []
    for i in range(0, len(M) - 1):
        row = []
        for j in range(0, len(M[0]) - 1):
            row = row + [M[i][j] + M[i][j+1] + M[i+1][j] + M[i+1][j+1]]
        P = P + [row]
    return P
